  padding: var(--sys-msg-padding) !important;
  background: var(--sys-msg-bg) !important;
  color: var(--sys-msg-color) !important;
  border-radius: var(--sys-msg-radius) !important;
  font-size: var(--sys-msg-font-size) !important;
  font-weight: 500 !important;
  backdrop-filter: var(--sys-msg-backdrop) !important;
  -webkit-backdrop-filter: var(--sys-msg-backdrop) !important;
  border: none !important;
  box-shadow: none !important;
}
.nuo-pat-msg {
  display: block !important;
  width: fit-content !important;
  margin: 12px auto !important;
  padding: var(--sys-msg-padding) !important;
  background: var(--sys-msg-bg) !important;
  color: var(--sys-msg-color) !important;
  border-radius: var(--sys-msg-radius) !important;
  font-size: var(--sys-msg-font-size) !important;
  backdrop-filter: var(--sys-msg-backdrop) !important;
