    align-items: stretch !important;
    padding: 0 !important;
    gap: 0 !important;
}
/* 靜音/翻轉/設定 → 螢幕右側竖排一列 */
.control-actions-row {
    position: absolute !important;
    right: 12px !important;
    bottom: 142px !important;
    width: auto !important;
    flex-direction: column !important;
    gap: 14px !important;
}
.control-btn-wrapper { flex-direction: column !important; }
.control-btn {
    width: 42px !important;
    height: 42px !important;
    background: rgba(0, 0, 0, 0.32) !important;
    backdrop-filter: blur(8px) !important;
}
.control-label { display: none !important; }

/* 掛斷鍵 → 右下角，抖音紅（安全護欄保證始終可點） */
.control-end-row {
    position: absolute !important;
    right: 12px !important;
    bottom: 88px !important;
    width: auto !important;
}
.end-call-btn {
    width: 46px !important;
    height: 46px !important;
    background: linear-gradient(135deg, #fe2c55, #ff5c8a) !important;
    box-shadow: 0 4px 18px rgba(254, 44, 85, 0.5) !important;
}

/* 歷史 / 自動播放 / 重生成 → 一起移到右側竖排（原本擠在左下與輸入欄重疊） */
.vc-aux-btn {
    left: auto !important;
    right: 14px !important;
    width: 38px !important;
    height: 38px !important;
}
.vc-aux-continue { bottom: 264px !important; }
.vc-aux-reroll   { bottom: 306px !important; }
.vc-aux-autoplay { bottom: 348px !important; }
.vc-aux-history  { bottom: 390px !important; }

/* —— 未輸入時：左下「說點什麼」提示膠囊（點麥克風/螢幕即喚出真實輸入） —— */
.video-call-controls::before {
    content: "說點什麼...";
    position: absolute;
    left: 12px;
    bottom: 18px;
    width: 48%;
    background: rgba(255,255,255,0.15);
    backdrop-filter: blur(8px);
    color: rgba(255,255,255,0.8);
    font-size: 13px;
    padding: 9px 16px;
    border-radius: 999px;
    pointer-events: none;
}

/* —— 輸入時：真實輸入欄移到底部左側，做成輸入膠囊 ——
   bottom 疊加全局鍵盤高度 var(--kb-h)（App.jsx useKeyboardScrollIntoView 維護），
   軟鍵盤彈出時自動頂到鍵盤上方，不被遮擋。 */
.vc-text-input-overlay {
    bottom: calc(14px + var(--kb-h, 0px)) !important;
    top: auto !important;
    padding: 0 12px !important;
    align-items: stretch !important;
    transition: bottom 0.2s ease !important;
}
.vc-text-input-overlay > div {
    width: 66% !important;
    background: rgba(20,20,22,0.7) !important;
    backdrop-filter: blur(10px) !important;
    border-radius: 22px !important;
    padding: 10px 16px !important;
    box-shadow: 0 4px 18px rgba(0,0,0,0.4) !important;
}
.vc-text-input-overlay #video-call-text-input {
    text-align: left !important;
    font-size: 14px !important;
    text-shadow: none !important;
}

